operations.schema:
input CreateWbsInput {
  id: OID!
  title: String!
  description: String
  budget: Float
  timeline: String
  createdAt: DateTime!
}

output CreateWbsOutput {
  id: OID!
}

operations.reducer:
const newWBS = {
  id: action.input.id,
  title: action.input.title,
  description: action.input.description || null,
  budget: action.input.budget || null,
  timeline: action.input.timeline || null,
  tasks: [],
  teamMembers: [],
  createdAt: action.input.createdAt,
  updatedAt: null
};

Object.assign(state, newWBS);

return {
  id: state.id
};

operations.schema:
input UpdateWbsInfoInput {
  title: String
  description: String
  budget: Float
  timeline: String
  updatedAt: DateTime!
}

output UpdateWbsInfoOutput {
  success: Boolean!
}

operations.reducer:
if (action.input.title !== undefined) {
  state.title = action.input.title;
}
if (action.input.description !== undefined) {
  state.description = action.input.description;
}
if (action.input.budget !== undefined) {
  state.budget = action.input.budget;
}
if (action.input.timeline !== undefined) {
  state.timeline = action.input.timeline;
}
state.updatedAt = action.input.updatedAt;

return {
  success: true
};

const newTask = {
  id: action.input.id,
  parentTaskId: action.input.parentTaskId || null,
  code: action.input.code,
  title: action.input.title,
  summary: action.input.summary || null,
  description: action.input.description || null,
  status: action.input.status,
  priority: action.input.priority,
  progress: 0,
  estimatedHours: action.input.estimatedHours || null,
  actualHours: null,
  startDate: action.input.startDate || null,
  dueDate: action.input.dueDate || null,
  createdAt: action.input.createdAt,
  updatedAt: null
};

state.tasks.push(newTask);
state.updatedAt = action.input.createdAt;

return {
  id: newTask.id
};
